@startuml

class Student {
  + studentId : string
}

class Course {
  + courseId : int
}

class TeachingAssistant {
  + taId : string
}

class Appointment {
  + appointmentId : int
}

Student "1" -- "0..*" Course : registered_for
TeachingAssistant "1" -- "0..*" Course : teaches
Appointment "1" -- "1" Student : made_by
Appointment "1" -- "1" TeachingAssistant : attended_by
Appointment "1" -- "1" Course : for_course

@enduml

